// ============================================================
// Build SerpAPI queries across 7 lead signal types
// Each day covers ALL signal types with rotating industries
// ============================================================
// Industries: D2C + SaaS + Fintech + Edtech + Healthtech + more
const allIndustries = [
  'skincare', 'fashion', 'fitness', 'food and beverage',
  'home decor', 'wellness', 'pet care', 'electronics', 'jewelry',
  'supplements', 'baby care', 'organic food', 'athleisure',
  'SaaS', 'fintech', 'edtech', 'healthtech', 'real estate',
  'gaming', 'logistics', 'insurtech', 'agritech', 'legaltech'
];

const now = new Date();
const startOfYear = new Date(now.getFullYear(), 0, 0);
const dayOfYear = Math.floor((now - startOfYear) / (1000 * 60 * 60 * 24));
const year = now.getFullYear();

// Rotate 4 industries per day (covers all 23 in ~6 days)
const startIdx = (dayOfYear * 4) % allIndustries.length;
const todayIndustries = [];
for (let i = 0; i < 4; i++) {
  todayIndustries.push(allIndustries[(startIdx + i) % allIndustries.length]);
}

const queries = [];

// === SIGNAL 1: Recently Funded Brands (D2C + tech) ===
queries.push({ query: `startup raised funding India ${year} D2C SaaS`, signal: 'funded', industry: 'general' });
queries.push({ query: `seed series A funding India ${year} startup`, signal: 'funded', industry: 'general' });
queries.push({ query: `Indian startup funding announcement ${year}`, signal: 'funded', industry: 'general' });

// === SIGNAL 2: Brands Running Meta/Google Ads ===
queries.push({ query: `brand advertising Instagram Facebook India ${year}`, signal: 'meta_ads', industry: 'general' });
queries.push({ query: `Indian startup scaling performance marketing paid ads`, signal: 'meta_ads', industry: 'general' });

// === SIGNAL 3: Hiring Marketing/Content Roles ===
queries.push({ query: `startup hiring content marketing manager India`, signal: 'hiring', industry: 'general' });
queries.push({ query: `"hiring" "growth marketing" startup India ${year}`, signal: 'hiring', industry: 'general' });

// === SIGNAL 4: Shark Tank / Business Reality Shows ===
queries.push({ query: `Shark Tank India brand ${year}`, signal: 'shark_tank', industry: 'general' });

// === SIGNAL 5: Marketplace to D2C Transition ===
queries.push({ query: `brand launching own website D2C India ${year}`, signal: 'marketplace_to_d2c', industry: 'general' });

// === SIGNAL 6: Creator/Influencer Collaborations ===
queries.push({ query: `brand influencer collaboration India ${year} UGC`, signal: 'creator_collab', industry: 'general' });

// === SIGNAL 7: Industry-Specific Discovery (rotating) ===
for (const industry of todayIndustries) {
  queries.push({ query: `best ${industry} brands India ${year}`, signal: 'industry_discovery', industry });
  queries.push({ query: `new ${industry} startup India growing`, signal: 'industry_discovery', industry });
}

const signalCounts = {};
for (const q of queries) {
  signalCounts[q.signal] = (signalCounts[q.signal] || 0) + 1;
}

return [{ json: { queries, industries: todayIndustries, signalCounts, totalQueries: queries.length, source: 'schedule' } }];

// ============================================================
// Search SerpAPI — collects both brand sites AND news articles
// News articles (funding, hiring, shark tank) contain brand names
// that Gemini will extract in the enrichment step
// ============================================================
const input = $input.first().json;
const queries = input.queries || [];
const SERP_API_KEY = 'b183c082b67f0971673dbab7ce0a14883f75e5012d09720d17c540efce67bc39';

// Helper: extract domain from URL without URL constructor
function getDomain(link) {
  if (!link) return '';
  const match = link.match(/^https?:\/\/(?:www\.)?([^\/?#]+)/i);
  return match ? match[1].toLowerCase() : '';
}

// News/article domains — results from these contain brand MENTIONS
// We keep them but flag as 'article' type for Gemini to extract brands
const articleDomains = new Set([
  'inc42.com', 'yourstory.com', 'entrackr.com', 'economictimes.indiatimes.com',
  'livemint.com', 'moneycontrol.com', 'businessinsider.in', 'techcrunch.com',
  'vccircle.com', 'dealstreetasia.com', 'thehindu.com', 'ndtv.com',
  'businesstoday.in', 'financialexpress.com', 'thehindubusinessline.com',
  'forbesindia.com', 'cnbctv18.com'
]);

// Completely useless domains to skip
const skipDomains = new Set([
  'wikipedia.org', 'google.com', 'facebook.com', 'twitter.com', 'x.com',
  'reddit.com', 'quora.com', 'pinterest.com', 'tiktok.com',
  'play.google.com', 'apps.apple.com', 'medium.com',
  'instagram.com', 'linkedin.com', 'amazon.in', 'amazon.com',
  'flipkart.com', 'myntra.com', 'nykaa.com', 'ajio.com',
  'youtube.com', 'crunchbase.com', 'zoominfo.com', 'tracxn.com',
  'wellfound.com', 'glassdoor.co.in', 'naukri.com', 'indeed.com'
]);

const allResults = [];
const seenUrls = new Set();
const signalHits = {};

for (let i = 0; i < queries.length; i++) {
  const q = queries[i];
  try {
    const url = `https://serpapi.com/search.json?engine=google&q=${encodeURIComponent(q.query)}&api_key=${SERP_API_KEY}&gl=in&hl=en&num=10`;
    const response = await this.helpers.httpRequest({ method: 'GET', url, json: true });
    const organicResults = response.organic_results || [];

    signalHits[q.signal] = (signalHits[q.signal] || 0) + organicResults.length;

    for (const result of organicResults) {
      const link = result.link || '';
      const domain = getDomain(link);
      if (!domain) continue;
      if (skipDomains.has(domain)) continue;
      if (seenUrls.has(link)) continue;
      seenUrls.add(link);

      const isArticle = articleDomains.has(domain) || domain.endsWith('.com') && (
        link.includes('/funding') || link.includes('/startup') ||
        link.includes('/news') || link.includes('/article')
      );

      const title = (result.title || '').trim();
      const snippet = (result.snippet || '').substring(0, 400);

      allResults.push({
        title,
        website: link,
        domain,
        snippet,
        industry: q.industry,
        signal: q.signal || 'unknown',
        search_query: q.query,
        is_article: isArticle
      });
    }
  } catch (err) {
    // Continue on individual query failure
  }

  // 1.2-second delay between requests
  if (i < queries.length - 1) {
    await new Promise(resolve => setTimeout(resolve, 1200));
  }
}

// Cap at 50 results
const capped = allResults.slice(0, 50);
const articleCount = capped.filter(r => r.is_article).length;
const directCount = capped.filter(r => !r.is_article).length;

return [{ json: {
  results: capped,
  totalFound: capped.length,
  articleResults: articleCount,
  directResults: directCount,
  queriesRun: queries.length,
  industries: input.industries || [],
  signalCounts: input.signalCounts || {},
  signalHits
} }];

// ============================================================
// Filter search results: remove existing leads (by domain)
// Keep BOTH article results AND direct brand results
// Articles will be processed by Gemini to extract brand names
// ============================================================
const searchData = $('SerpAPI Search').first().json;
const existingResponse = $input.first().json;

const results = searchData.results || [];
const existingRecords = (existingResponse.records || []).map(r => r.fields || {});

// Build set of existing domains from Airtable
const existingDomains = new Set();
const existingNames = new Set();
for (const rec of existingRecords) {
  if (rec.company_name) existingNames.add(rec.company_name.toLowerCase().trim());
  if (rec.website) {
    const match = rec.website.match(/^https?:\/\/(?:www\.)?([^\/?#]+)/i);
    if (match) existingDomains.add(match[1].toLowerCase());
  }
}

let duplicatesRemoved = 0;
const filtered = [];

for (const r of results) {
  // For articles (news sites), always keep them — they mention brand names
  if (r.is_article) {
    filtered.push(r);
    continue;
  }

  // For direct brand websites, check if already in our Leads
  const domain = (r.domain || '').toLowerCase();
  if (domain && existingDomains.has(domain)) { duplicatesRemoved++; continue; }

  // Also check company name fuzzy match
  const titleLower = r.title.toLowerCase();
  let nameMatch = false;
  for (const name of existingNames) {
    if (name.length > 3 && titleLower.includes(name)) { nameMatch = true; break; }
  }
  if (nameMatch) { duplicatesRemoved++; continue; }

  filtered.push(r);
}

return [{ json: {
  searchResults: filtered,
  totalFound: results.length,
  keptResults: filtered.length,
  duplicatesRemoved,
  articleCount: filtered.filter(r => r.is_article).length,
  directCount: filtered.filter(r => !r.is_article).length,
  existingLeadCount: existingRecords.length,
  industries: searchData.industries || [],
  signalCounts: searchData.signalCounts || {},
  signalHits: searchData.signalHits || {}
} }];

// ============================================================
// Build Gemini prompt — extract brands + score for all services
// Cosmisk: UGC ads, AI ads, mashup ads, media buying
// Targets: D2C, SaaS, Fintech, Edtech, Healthtech, etc.
// ============================================================
const data = $input.first().json;
const results = (data.searchResults || []).slice(0, 15);

const signalLabels = {
  funded: 'Recently Funded',
  meta_ads: 'Running Meta/Google Ads',
  hiring: 'Hiring Marketing Roles',
  shark_tank: 'Shark Tank / TV Appearance',
  marketplace_to_d2c: 'Marketplace to D2C Transition',
  creator_collab: 'Creator Collaborations',
  industry_discovery: 'Industry Search',
  custom: 'Custom Search'
};

const systemPrompt = `You are a business development analyst for Cosmisk, a creative agency in India. Cosmisk offers:
- UGC ads (creator-driven video content for paid ads)
- AI-generated ads and mashup ads
- Performance media buying (Meta + Google)
- Ad account audits and creative strategy

We work with ALL growth-stage companies: D2C, SaaS, Fintech, Edtech, Healthtech, Real Estate, Gaming, and more.

You have TWO jobs:

**JOB 1 — Extract company names from news articles:**
Some results are NEWS ARTICLES (from inc42, yourstory, entrackr, techcrunch, etc.). Extract ACTUAL COMPANY NAMES mentioned. Each article may mention 1-5 companies.

**JOB 2 — Score all companies for creative services readiness:**
For every company, evaluate:
1. Company name (clean name only)
2. Website URL (from snippet or your knowledge, or empty)
3. Industry (be specific: skincare, SaaS, fintech, edtech, fashion, etc.)
4. Discovery signal (funded/meta_ads/hiring/shark_tank/marketplace_to_d2c/creator_collab/industry_discovery)
5. Opportunity score 1-10:
   - Recently funded: +2 (budget to spend)
   - Running digital ads: +2 (understand paid content)
   - Shark Tank/high visibility: +2 (need content fast)
   - B2C or prosumer model: +1
   - Active social presence: +1
   - SaaS/Fintech scaling: +1 (need explainer + testimonial content)
   - Base: 3 for any real company
6. Contact title (Founder, CMO, VP Marketing, Growth Head)
7. Best Cosmisk service for them (ugc_ads / ai_ads / mashup_ads / media_buying / full_stack)
8. Brief outreach notes (why they need our services)
9. Suggested outreach platform (instagram_dm / email / linkedin)
10. One-line personalized pitch hook

**RULES:**
- Do NOT include news sites, media companies, or marketplaces
- Include D2C brands, SaaS companies, fintech startups, edtech, healthtech — any growth company
- Deduplicate — if same company appears in multiple articles, include once
- Return 5-15 qualified companies (score >= 6)

Return ONLY a valid JSON array. Keys:
{ company_name, website, industry, signal, score, contact_title, best_service, notes, suggested_platform, pitch_hook }`;

const resultList = results.map((r, i) => {
  const sig = signalLabels[r.signal] || r.signal;
  const type = r.is_article ? 'NEWS ARTICLE' : 'COMPANY WEBSITE';
  return `${i + 1}. [${type}] [Signal: ${sig}]\n   Title: ${r.title}\n   URL: ${r.website}\n   Snippet: ${r.snippet}`;
}).join('\n\n');

const userPrompt = `Here are ${results.length} search results from Google India. Extract companies and score them for Cosmisk's creative services (UGC ads, AI ads, mashup ads, media buying):\n\n${resultList}\n\nExtract all companies mentioned, deduplicate, score them, and return the JSON array.`;

return [{ json: {
  systemPrompt,
  userPrompt,
  rawResults: results,
  allData: data
} }];

// ============================================================
// Parse Gemini brand extraction + scoring results
// Builds Airtable batch create + signal-rich Slack report
// HARDENED junk filter v2 — rejects article titles, TV shows,
// news aggregators, Instagram handles, and overly long names
// ============================================================
const geminiResponse = $input.first().json;
const prevData = $('Build Enrich Prompt').first().json;
const rawResults = prevData.rawResults || [];
const allData = prevData.allData || {};

const signalEmojis = {
  funded: ':moneybag:',
  meta_ads: ':bar_chart:',
  hiring: ':briefcase:',
  shark_tank: ':shark:',
  marketplace_to_d2c: ':shopping_trolley:',
  creator_collab: ':handshake:',
  industry_discovery: ':mag:',
  custom: ':dart:'
};

const signalLabels = {
  funded: 'Funded',
  meta_ads: 'Running Ads',
  hiring: 'Hiring',
  shark_tank: 'Shark Tank',
  marketplace_to_d2c: 'Marketplace→D2C',
  creator_collab: 'Creator Collabs',
  industry_discovery: 'Industry Match',
  custom: 'Custom'
};

let brands = [];
let geminiWorked = false;

try {
  const text = (geminiResponse.candidates || [])[0]?.content?.parts?.[0]?.text || '';
  if (!text) throw new Error('No text in Gemini response');

  // Strip markdown code fences
  let cleaned = text.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();

  // Try parsing the full response first
  try {
    const arrMatch = cleaned.match(/\[[\s\S]*\]/);
    if (arrMatch) {
      brands = JSON.parse(arrMatch[0]);
    } else {
      brands = JSON.parse(cleaned);
    }
  } catch (parseErr) {
    // JSON may be truncated (MAX_TOKENS) — salvage complete objects
    const objectPattern = /\{[^{}]*"company_name"\s*:\s*"[^"]+\"[^{}]*\}/g;
    const matches = cleaned.match(objectPattern) || [];
    for (const m of matches) {
      try {
        const obj = JSON.parse(m);
        if (obj.company_name) brands.push(obj);
      } catch (e) { /* skip malformed */ }
    }
  }

  if (brands.length > 0) geminiWorked = true;
} catch (err) {
  // Total Gemini failure
}

// If Gemini didn't extract any brands, DON'T create junk leads — just report
if (brands.length === 0) {
  const sigSummary = Object.entries(allData.signalHits || {}).map(([k, v]) => `${signalLabels[k] || k}: ${v}`).join(', ');
  return [{ json: {
    batchBody: { records: [] },
    slackMsg: `:telescope: *Prospect Finder — Gemini Could Not Extract Brands*\n\nSignals searched: ${sigSummary || 'N/A'}\nSearch results found: ${allData.totalFound || 0} (${allData.articleCount || 0} articles, ${allData.directCount || 0} direct)\n\n_Gemini enrichment failed or returned no qualifying brands. Check execution logs._`,
    count: 0,
    highScoreProspects: [],
    industries: allData.industries || []
  } }];
}

// Map signal labels back to signal keys for consistent data
const labelToKey = {};
for (const [k, v] of Object.entries(signalLabels)) labelToKey[v.toLowerCase()] = k;
for (const b of brands) {
  if (b.signal && !signalEmojis[b.signal]) {
    const mapped = labelToKey[(b.signal || '').toLowerCase()];
    if (mapped) b.signal = mapped;
  }
}

// ============================================================
// HARDENED JUNK FILTER — reject non-brand names
// ============================================================
function isJunkCompanyName(name) {
  if (!name || typeof name !== 'string') return true;
  const trimmed = name.trim();
  const lower = trimmed.toLowerCase();

  // Length checks: must be 2-40 chars (real brand names)
  if (trimmed.length < 2 || trimmed.length > 40) return true;

  // Reject overly long names (> 50 chars before trim — catches long article titles)
  if (name.length > 50) return true;

  // Reject names starting with a number followed by article keywords
  // e.g. "10 Top D2C Brands", "5 Best Indian Startups"
  if (/^\d+\s*(top|best|leading|most)\b/i.test(trimmed)) return true;

  // Reject news aggregation / tracker patterns
  if (/\b(latest|updates|tracker|status)\b/i.test(trimmed)) return true;

  // Reject Instagram handles (contains @)
  if (trimmed.includes('@')) return true;

  // Reject TV show references
  if (/\b(season|S4|S5|S6|S7|S8|S9|S10|S11|S12)\b/i.test(trimmed)) return true;

  // Reject article-like titles: starts with "Top", "Best", "Leading", "Most"
  if (/^(top|best|leading|most)\s/i.test(trimmed)) return true;

  // Reject names that look like list articles: "X Brands to Watch"
  if (/\b(brands?\s+to\s+watch|companies?\s+to\s+watch|startups?\s+to\s+watch)\b/i.test(trimmed)) return true;

  // Reject pure numeric names
  if (/^\d+$/.test(trimmed)) return true;

  // Reject names with too many words (likely a sentence, not a brand)
  if (trimmed.split(/\s+/).length > 6) return true;

  return false;
}

// Filter to score >= 6, deduplicate by name, AND apply hardened junk filter
const seen = new Set();
const qualified = [];
let junkFiltered = 0;
for (const b of brands) {
  if ((b.score || 0) < 6) continue;
  const rawName = (b.company_name || '').trim();

  // Apply hardened junk filter
  if (isJunkCompanyName(rawName)) {
    junkFiltered++;
    continue;
  }

  const key = rawName.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  qualified.push(b);
}

if (qualified.length === 0) {
  const sigSummary = Object.entries(allData.signalHits || {}).map(([k, v]) => `${signalLabels[k] || k}: ${v} hits`).join(', ');
  return [{ json: {
    batchBody: { records: [] },
    slackMsg: `:telescope: *Prospect Finder — No Qualified Brands Today*\n\nSignals: ${sigSummary || 'N/A'}\nSearch results: ${allData.totalFound || 0} (${allData.articleCount || 0} articles, ${allData.directCount || 0} direct)\nJunk names filtered: ${junkFiltered}\n\n_Gemini didn't find any qualifying D2C brands. Will try different queries tomorrow._`,
    count: 0,
    highScoreProspects: [],
    industries: allData.industries || []
  } }];
}

// Build Airtable batch create — max 10 per API call
const records = qualified.slice(0, 10).map(b => ({
  fields: {
    company_name: b.company_name,
      source: 'prospect_finder',
      email: (b.email && typeof b.email === 'string' && b.email.includes('@')) ? b.email.trim() : undefined || 'Unknown',
    contact_name: b.contact_title || '(To find)',
    stage: 'New',
    website: b.website || '',
    notes: `Source: Prospect Finder (auto-discovered)\nBest Service: ${b.best_service || 'ugc_ads'}\nDiscovery Signal: ${signalLabels[b.signal] || b.signal || 'N/A'}\nIndustry: ${b.industry || 'N/A'}\nUGC Score: ${b.score}/10\nOutreach: ${b.suggested_platform || 'instagram_dm'}\nPitch: ${b.pitch_hook || 'N/A'}\nAI Notes: ${b.notes || 'N/A'}`
  }
}));

const batchBody = { records };

// Slack report — top 8 prospects with signal tags and pitch hooks
const topProspects = qualified.sort((a, b) => (b.score || 0) - (a.score || 0)).slice(0, 8);

let slackLines = topProspects.map((p, i) => {
  const emoji = signalEmojis[p.signal] || ':mag:';
  const sigLabel = signalLabels[p.signal] || p.signal || '';
  const hook = p.pitch_hook ? `\n   _${p.pitch_hook}_` : '';
  return `${i + 1}. ${emoji} *${p.company_name}* (${p.industry || '?'}) — Score: ${p.score}/10\n   ${p.website || 'website unknown'}\n   Signal: ${sigLabel} | Outreach via: ${p.suggested_platform || 'instagram'}${hook}`;
}).join('\n\n');

// Signal breakdown
const sigBreakdown = {};
for (const p of qualified) {
  const s = p.signal || 'unknown';
  sigBreakdown[s] = (sigBreakdown[s] || 0) + 1;
}
const sigLine = Object.entries(sigBreakdown).map(([k, v]) => `${signalEmojis[k] || ''} ${signalLabels[k] || k}: ${v}`).join(' | ');

const slackMsg = `:telescope: *Prospect Finder — ${qualified.length} D2C Brands Discovered*\n\n*Signal Breakdown:* ${sigLine}\nIndustries: ${(allData.industries || []).join(', ')}\nSearch results analyzed: ${allData.totalFound || 0} (${allData.articleCount || 0} articles, ${allData.directCount || 0} direct sites)\nDuplicates filtered: ${allData.duplicatesRemoved || 0} | Junk filtered: ${junkFiltered} | Brands extracted & qualified: ${qualified.length}\n${geminiWorked ? '' : ':warning: Gemini failed — using fallback scoring\n'}\n*Top Prospects:*\n\n${slackLines}${qualified.length > 8 ? '\n\n_...and ' + (qualified.length - 8) + ' more in Airtable_' : ''}\n\n_All prospects auto-added to Leads pipeline with pitch hooks. Review in #ugc-outreach._`;

return [{ json: {
  batchBody,
  slackMsg,
  count: qualified.length,
  highScoreProspects: topProspects,
  industries: allData.industries || [],
  signalBreakdown: sigBreakdown,
  junkFiltered
} }];

// ============================================================
// Parse webhook body — accept custom industries, signals, or queries
// POST /find-prospects { industries?, signals?, queries? }
// signals: 'funded' | 'meta_ads' | 'hiring' | 'shark_tank' |
//          'marketplace_to_d2c' | 'creator_collab' | 'industry_discovery'
// ============================================================
const body = $input.first().json.body || $input.first().json;
const year = new Date().getFullYear();

const allIndustries = [
  'skincare', 'fashion', 'fitness', 'food and beverage',
  'home decor', 'wellness', 'pet care', 'electronics', 'jewelry',
  'supplements', 'baby care', 'organic food', 'athleisure',
  'SaaS', 'fintech', 'edtech', 'healthtech', 'real estate',
  'gaming', 'logistics', 'insurtech', 'agritech', 'legaltech'
];

const queries = [];
let selectedIndustries = body.industries || [];
if (selectedIndustries.length === 0) {
  const shuffled = [...allIndustries].sort(() => Math.random() - 0.5);
  selectedIndustries = shuffled.slice(0, 3);
}

// If custom queries provided, use them directly
if (body.queries && Array.isArray(body.queries) && body.queries.length > 0) {
  for (const q of body.queries) queries.push({ query: q, signal: 'custom', industry: 'custom' });
} else {
  // Build queries from requested signals (default: all)
  const signals = body.signals || ['funded', 'meta_ads', 'hiring', 'shark_tank', 'marketplace_to_d2c', 'creator_collab', 'industry_discovery'];
  const signalSet = new Set(signals);

  if (signalSet.has('funded')) {
    queries.push({ query: `D2C brand raised funding India ${year}`, signal: 'funded', industry: 'general' });
    queries.push({ query: `D2C startup seed series A India ${year}`, signal: 'funded', industry: 'general' });
  }
  if (signalSet.has('meta_ads')) {
    queries.push({ query: `D2C brand advertising on Instagram India ${year}`, signal: 'meta_ads', industry: 'general' });
    queries.push({ query: `Indian D2C brands scaling performance marketing`, signal: 'meta_ads', industry: 'general' });
  }
  if (signalSet.has('hiring')) {
    queries.push({ query: `D2C brand hiring content marketing manager India`, signal: 'hiring', industry: 'general' });
  }
  if (signalSet.has('shark_tank')) {
    queries.push({ query: `Shark Tank India brand ${year}`, signal: 'shark_tank', industry: 'general' });
  }
  if (signalSet.has('marketplace_to_d2c')) {
    queries.push({ query: `Amazon seller launched own website D2C India`, signal: 'marketplace_to_d2c', industry: 'general' });
  }
  if (signalSet.has('creator_collab')) {
    queries.push({ query: `D2C brand influencer collaboration India ${year}`, signal: 'creator_collab', industry: 'general' });
  }
  if (signalSet.has('industry_discovery')) {
    for (const ind of selectedIndustries) {
      queries.push({ query: `best D2C ${ind} brands India ${year}`, signal: 'industry_discovery', industry: ind });
    }
  }
}

const signalCounts = {};
for (const q of queries) signalCounts[q.signal] = (signalCounts[q.signal] || 0) + 1;

return [{ json: { queries, industries: selectedIndustries, signalCounts, totalQueries: queries.length, source: 'webhook' } }];

// ============================================================
// Final deduplication gate — remove any prospects from the batch
// whose company_name already exists in the Leads table.
// This catches leads created between the initial fetch and now
// (e.g., by Sales Pipeline or manual entry).
// ============================================================
const parseData = $('Parse Enriched Prospects').first().json;
const existingResponse = $input.first().json;

