// HARDENED JUNK FILTER — reject non-brand names
// ============================================================
function isJunkCompanyName(name) {
  if (!name || typeof name !== 'string') return true;
  const trimmed = name.trim();
  const lower = trimmed.toLowerCase();

  // Length checks: must be 2-40 chars (real brand names)
  if (trimmed.length < 2 || trimmed.length > 40) return true;

  // Reject overly long names (> 50 chars before trim — catches long article titles)
  if (name.length > 50) return true;

  // Reject names starting with a number followed by article keywords
  // e.g. "10 Top D2C Brands", "5 Best Indian Startups"
  if (/^\d+\s*(top|best|leading|most)\b/i.test(trimmed)) return true;

  // Reject news aggregation / tracker patterns
  if (/\b(latest|updates|tracker|status)\b/i.test(trimmed)) return true;

  // Reject Instagram handles (contains @)
  if (trimmed.includes('@')) return true;

  // Reject TV show references
  if (/\b(season|S4|S5|S6|S7|S8|S9|S10|S11|S12)\b/i.test(trimmed)) return true;

  // Reject article-like titles: starts with "Top", "Best", "Leading", "Most"
  if (/^(top|best|leading|most)\s/i.test(trimmed)) return true;

  // Reject names that look like list articles: "X Brands to Watch"
  if (/\b(brands?\s+to\s+watch|companies?\s+to\s+watch|startups?\s+to\s+watch)\b/i.test(trimmed)) return true;

  // Reject pure numeric names
  if (/^\d+$/.test(trimmed)) return true;

  // Reject names with too many words (likely a sentence, not a brand)
  if (trimmed.split(/\s+/).length > 6) return true;

  return false;
}

