  const shuffled = [...allIndustries].sort(() => Math.random() - 0.5);
  selectedIndustries = shuffled.slice(0, 3);
}

// If custom queries provided, use them directly
if (body.queries && Array.isArray(body.queries) && body.queries.length > 0) {
  for (const q of body.queries) queries.push({ query: q, signal: 'custom', industry: 'custom' });
} else {
  // Build queries from requested signals (default: all)
  const signals = body.signals || ['funded', 'meta_ads', 'hiring', 'shark_tank', 'marketplace_to_d2c', 'creator_collab', 'industry_discovery'];
  const signalSet = new Set(signals);

  if (signalSet.has('funded')) {
    queries.push({ query: `D2C brand raised funding India ${year}`, signal: 'funded', industry: 'general' });
    queries.push({ query: `D2C startup seed series A India ${year}`, signal: 'funded', industry: 'general' });
  }
  if (signalSet.has('meta_ads')) {
    queries.push({ query: `D2C brand advertising on Instagram India ${year}`, signal: 'meta_ads', industry: 'general' });
    queries.push({ query: `Indian D2C brands scaling performance marketing`, signal: 'meta_ads', industry: 'general' });
  }
  if (signalSet.has('hiring')) {
    queries.push({ query: `D2C brand hiring content marketing manager India`, signal: 'hiring', industry: 'general' });
  }
  if (signalSet.has('shark_tank')) {
    queries.push({ query: `Shark Tank India brand ${year}`, signal: 'shark_tank', industry: 'general' });
  }
  if (signalSet.has('marketplace_to_d2c')) {
    queries.push({ query: `Amazon seller launched own website D2C India`, signal: 'marketplace_to_d2c', industry: 'general' });
  }
  if (signalSet.has('creator_collab')) {
    queries.push({ query: `D2C brand influencer collaboration India ${year}`, signal: 'creator_collab', industry: 'general' });
  }
  if (signalSet.has('industry_discovery')) {
    for (const ind of selectedIndustries) {
      queries.push({ query: `best D2C ${ind} brands India ${year}`, signal: 'industry_discovery', industry: ind });
    }
  }
}

const signalCounts = {};
for (const q of queries) signalCounts[q.signal] = (signalCounts[q.signal] || 0) + 1;

return [{ json: { queries, industries: selectedIndustries, signalCounts, totalQueries: queries.length, source: 'webhook' } }];

// ============================================================
// Final deduplication gate — remove any prospects from the batch
// whose company_name already exists in the Leads table.
// This catches leads created between the initial fetch and now
// (e.g., by Sales Pipeline or manual entry).
// ============================================================
const parseData = $('Parse Enriched Prospects').first().json;
const existingResponse = $input.first().json;

const batchBody = parseData.batchBody || { records: [] };
const slackMsg = parseData.slackMsg || '';
const count = parseData.count || 0;

// If no records to create, pass through as-is
if (!batchBody.records || batchBody.records.length === 0) {
  return [{ json: parseData }];
}

// Build set of existing company names (lowercased)
const existingNames = new Set();
const existingRecords = (existingResponse.records || []).map(r => r.fields || {});
for (const rec of existingRecords) {
  if (rec.company_name) {
    existingNames.add(rec.company_name.toLowerCase().trim());
  }
}

// Filter out any prospect whose company_name already exists
let dedupRemoved = 0;
const filteredRecords = batchBody.records.filter(rec => {
  const name = (rec.fields?.company_name || '').toLowerCase().trim();
  if (existingNames.has(name)) {
    dedupRemoved++;
    return false;
  }
  return true;
});

// Update the output
const updatedBatchBody = { records: filteredRecords };
const finalCount = filteredRecords.length;

// If all were duplicates, update the slack message
let finalSlackMsg = slackMsg;
if (dedupRemoved > 0) {
  finalSlackMsg = slackMsg.replace(
    /Brands extracted & qualified: \d+/,
    `Brands extracted & qualified: ${finalCount} (${dedupRemoved} last-minute duplicates removed)`
  );
}

// If no records left after dedup, update message
if (finalCount === 0 && dedupRemoved > 0) {
  finalSlackMsg = `:telescope: *Prospect Finder — All Prospects Already Exist*\n\nAll ${dedupRemoved} qualified prospects were already in the Leads table.\n\n_No new leads created. Will try different queries next run._`;
}

return [{ json: {
  ...parseData,
  batchBody: updatedBatchBody,
  slackMsg: finalSlackMsg,
  count: finalCount,
  lastMinuteDedupRemoved: dedupRemoved
} }];
